// @match        https://www.torn.com/*
// @grant        none
// @noframes
// ==/UserScript==

/*
 * Torn Arcade - Character Art - an optional add-on for TORN ARCADE by Eaglewing [571041]
 *
 * WHAT IT DOES
 * - Contains the illustrated portraits of the gym leaders, story characters, trainers and player outfits, as small WebP images stored as text inside this script
 *   (custom illustrated artwork made specifically for Torn Arcade).
 * - When Torn Arcade asks for it (a 'ta-art-request' event on the page), it hands the pictures over with a
 *   'ta-art-pack' event on the same page. That is all it does. Torn Arcade checks every picture before using it.
 * - It makes no network requests, never reads or changes Torn's page, stores nothing and needs no API key.
 * - Without it, Torn Arcade still works and uses its pixel-art versions instead.
 *
 * TERMS OF SERVICE
 * - Data Storage:          No (nothing is stored)
 * - Data Sharing:          Nobody
 * - Purpose of Use:        Public amusement (artwork for the Torn Arcade games)
 * - Key Storage & Sharing: Not stored / Not shared (no key is used)
 * - Key Access Level:      None (no API key needed)
 *
 * LICENCE
 * All rights reserved. You may install and use this script as published. Copying, modifying, re-uploading or
 * redistributing it, in whole or in part, is not allowed without written permission from Eaglewing [571041].
 */

(function () {
  'use strict';
  const PACK = 'chars', VER = 1;
  const ITEMS = {
    'ace': '',
    'aide': '',
    'anton': '',
    'biker': '',
    'blonde': '',
    'bogie': '',
    'boss': '',
    'bouncer': '',
    'brick': '',
    'bug': '',
    'builder': '',
    'camper': '',
    'castaway': '',
    'casual': '',
    'chedburn': '',
    'chef': '',
    'clansdancer': '',
    'clerk': '',
    'cloud': '',
    'collector': '',
    'dealer': '',
    'disco': '',
    'driver': '',
    'duke': '',
    'eagle': '',
    'exec': '',
    'fighter': '',
    'fisher': '',
    'forge': '',
    'gent': '',
    'ghost': '',
    'graves': '',
    'guide': '',
    'hacker': '',
    'hiker': '',
    'ivy': '',
    'jacko': '',
    'jogger': '',
    'julie': '',
    'lady': '',
    'lass': '',
    'leslie': '',
    'magician': '',
    'man': '',
    'mohawk': '',
    'mom': '',
    'nurse': '',
    'office': '',
    'oldman': '',
    'outfit0': '',
    'outfit1': '',
    'outfit2': '',
    'outfit3': '',
    'pawl': '',
    'police': '',
    'prof': '',
    'punk': '',
    'racer': '',
    'reef': '',
    'rhea': '',
    'rival': '',
    'rookie': '',
    'sailor': '',
    'scholar': '',
    'scientist': '',
    'seadog': '',
    'sister': '',
    'skier': '',
    'sporty': '',
    'swimmer': '',
    'thug': '',
    'thug2': '',
    'veteran': '',
    'volta': '',
    'warden': '',
    'woman': '',
    'worker': ''
  };
  let payload = null;
  function send() {
    if (!payload) payload = JSON.stringify({ pack: PACK, ver: VER, items: ITEMS });
    document.dispatchEvent(new CustomEvent('ta-art-pack', { detail: payload }));
  }
  document.addEventListener('ta-art-request', send);   // Torn Arcade asks (whenever it starts or the art is switched on)
  send();                                              // and announce once, in case Torn Arcade started first
})();
